(() => {
  'use strict';
  const E = globalThis.QuizEngine;
  const bank = [...(globalThis.QUESTION_PART_12 || []), ...(globalThis.QUESTION_PART_3 || []), ...(globalThis.QUESTION_PART_45 || [])];
  const app = document.getElementById('app');
  const dialog = document.getElementById('confirm-dialog');
  const KEY = 'tram-on-tap-v1';
  const lookup = new Map(bank.map(q => [q.id, q]));
  const icons = { grid: 'M3 3h7v7H3z M14 3h7v7h-7z M3 14h7v7H3z M14 14h7v7h-7z', book: 'M3 4h6a4 4 0 0 1 3 1 4 4 0 0 1 3-1h6v16h-6a4 4 0 0 0-3 1 4 4 0 0 0-3-1H3z M12 5v16', file: 'M14 2H5v20h14V7z M14 2v6h5 M8 12h8 M8 16h6', clock: 'M12 8v5l3 2 M22 12a10 10 0 1 1-20 0 10 10 0 0 1 20 0', arrow: 'M4 12h16 M14 6l6 6-6 6', check: 'M5 12l4 4L19 6', flag: 'M5 22V3 M5 3c5-4 9 4 14 0v10c-5 4-9-4-14 0', history: 'M3 3v6h6 M3 9a9 9 0 1 1 0 6 M12 7v6l4 2', leaf: 'M20 3c-13-2-18 7-13 12 5 5 14 0 13-12z M4 21L15 9', close: 'M6 6l12 12 M6 18L18 6', bolt: 'M13 2L4 14h7l-1 8 10-13h-7z' };
  const icon = (name, cls = '') => `<svg class="icon ${cls}" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.7" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="${icons[name] || icons.book}"/></svg>`;
  const esc = value => String(value ?? '').replace(/[&<>"']/g, c => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;' }[c]));
  const btn = (action, text, cls = 'primary', attrs = '') => `<button class="btn ${cls}" data-action="${action}" ${attrs}>${text}</button>`;
  let state = { active: null, history: [], reviewId: null }, route = 'home', review = null, reviewFilter = 'all', confirmAction = null, storageWarning = false;
  try { E.validateBank(bank); } catch (error) { app.innerHTML = `<main class="fatal"><h1>Chưa tải đủ câu hỏi</h1><p>${esc(error.message)}</p><p>Hãy mở lại trang để thử lại.</p><button class="btn primary" onclick="location.reload()">Tải lại</button></main>`; return; }
  try {
    const saved = JSON.parse(localStorage.getItem(KEY));
    if (saved) { state.active = E.isValidAttempt(saved.active, bank) ? saved.active : null; state.history = Array.isArray(saved.history) ? saved.history.filter(a => E.isValidAttempt(a, bank) && a.status === 'done').slice(0, 30) : []; state.reviewId = typeof saved.reviewId === 'string' ? saved.reviewId : null; }
  } catch { storageWarning = true; }
  function toast(message) { const el = document.getElementById('toast'); el.textContent = message; el.classList.add('visible'); clearTimeout(toast.timer); toast.timer = setTimeout(() => el.classList.remove('visible'), 4500); }
  function save() { try { localStorage.setItem(KEY, JSON.stringify(state)); } catch { if (!storageWarning) toast('Trình duyệt không lưu được tiến độ. Hãy giữ trang mở khi làm bài.'); storageWarning = true; } }
  function confirm(title, copy, action, label) { document.getElementById('dialog-title').textContent = title; document.getElementById('dialog-copy').textContent = copy; dialog.querySelector('[value="submit"]').textContent = label; confirmAction = action; dialog.returnValue = ''; dialog.showModal(); }
  dialog.addEventListener('close', () => { const action = confirmAction; confirmAction = null; if (dialog.returnValue === 'submit' && action) action(); });
  function summary() {
    const grades = state.history.map(a => E.grade(a, bank));
    return { count: grades.length, best: grades.length ? Math.max(...grades.map(g => g.score)).toFixed(1) : '—', average: grades.length ? (grades.reduce((s, g) => s + g.score, 0) / grades.length).toFixed(1) : '—' };
  }
  function chapterStats(id) { const rows = state.history.flatMap(a => E.grade(a, bank).rows).filter(q => q.chapter === id); return { count: rows.length, percent: rows.length ? Math.round(rows.filter(q => q.correct).length / rows.length * 100) : 0 }; }
  function shell(content, selected = route) {
    const navs = [['home', 'grid', 'Góc học tập'], ['exams', 'file', 'Kho đề thi thử'], ['chapters', 'book', 'Luyện theo bài'], ['history', 'history', 'Lịch sử làm bài'], ['sources', 'leaf', 'Tài liệu & phạm vi']];
    app.innerHTML = `<aside class="sidebar"><a href="#home" class="brand"><span class="brand-mark">${icon('check')}</span><span>trạm ôn tập<span class="brand-sub">HỌC CHẮC, THI TỰ TIN.</span></span></a><div class="course-label">KHÔNG GIAN CỦA BẠN</div><nav aria-label="Điều hướng chính">${navs.map(([id, i, label]) => `<a href="#${id}" class="nav-item ${selected === id ? 'active' : ''}" ${selected === id ? 'aria-current="page"' : ''}>${icon(i)}<span>${label}</span>${id === 'exams' ? '<span class="nav-count">12</span>' : ''}</a>`).join('')}</nav><div class="sidebar-note"><span class="tiny-label">MỖI NGÀY MỘT CHÚT</span><p>Hiểu vì sao đúng.<br>Nhớ lâu hơn một đáp án.</p><div class="mini-line"></div><small>Kiểm thử phần mềm<br>Bài 01 — 05</small></div><div class="sidebar-bottom"><span class="status-dot"></span> Tiến độ lưu trên máy này</div></aside><div class="workspace"><header class="topbar"><span>KIỂM THỬ PHẦN MỀM <span class="top-divider">/</span> <span class="top-muted">Ôn tập cá nhân</span></span><span class="language">VI <span>Tiếng Việt</span></span></header><main id="main" tabindex="-1">${content}</main><footer><span>trạm ôn tập <span class="footer-dot">·</span> Một lần luyện, một bước chắc hơn.</span><span>Câu hỏi tự biên soạn từ tài liệu môn học</span></footer></div>`;
  }
  function heading(kicker, title, sub, aside = '') { return `<div class="page-heading"><div><div class="eyebrow">${kicker}</div><h1 tabindex="-1">${title}</h1><p class="page-sub">${sub}</p></div>${aside}</div>`; }
  function home() {
    const s = summary();
    const active = state.active?.status === 'active';
    shell(`${heading('SẴN SÀNG CHO BÀI KIỂM TRA', 'Chào bạn, mình cùng ôn nhé.', 'Kiến thức vững hơn, từng câu một.', '<div class="exam-date">'+icon('clock')+'<div><small>NGÀY KIỂM TRA</small><strong>Thứ Sáu, 13/11/2026</strong></div></div>')}
      <div class="home-grid"><section class="exam-feature"><div class="feature-content"><span class="pill light"><span class="status-dot"></span> ĐÚNG CẤU TRÚC BÀI KIỂM TRA</span><h2>Một đề thử.<br>Thêm một lần tự tin.</h2><p>Trộn câu hỏi từ cả 5 bài. Thử sức như lúc kiểm tra,<br class="desktop-break"> rồi xem lại để hiểu điều mình còn thiếu.</p><div class="exam-facts"><div><strong>30</strong><span>câu hỏi</span></div><div><strong>45</strong><span>phút làm bài</span></div><div><strong>6</strong><span>câu / bài</span></div></div>${active ? btn('resume', 'Tiếp tục bài đang làm '+icon('arrow'), 'cream') : btn('random', 'Bắt đầu đề ngẫu nhiên '+icon('arrow'), 'cream')}<span class="feature-note">${active ? 'Câu trả lời trước đó đã được lưu' : 'Có đáp án & giải thích sau khi nộp bài'}</span></div><div class="paper-art" aria-hidden="true"><div class="paper-back"></div><div class="paper-sheet"><div class="paper-top">BÀI THI THỬ <span>01</span></div><div class="paper-rule"></div><div class="paper-question">Sẵn sàng<br>thử sức?</div><div class="paper-option"><i></i><span></span></div><div class="paper-option checked"><i>✓</i><span></span></div><div class="paper-option"><i></i><span></span></div><div class="paper-option"><i></i><span></span></div><div class="paper-stamp">30 CÂU<br><b>45 PHÚT</b></div></div><div class="spark s1">✳</div><div class="spark s2">+</div></div></section>
      <aside class="study-note"><div class="note-pin"></div><span class="eyebrow">MỘT NHẮC NHỎ</span><h2>Đừng chỉ nhớ<br>đáp án.</h2><p>Sau mỗi đề, dành vài phút đọc giải thích câu sai. Đó là lúc bạn tiến bộ nhiều nhất.</p><div class="note-bottom">Chậm một chút, chắc hơn nhiều.<span>↗</span></div></aside></div>
      <section class="stats-row" aria-label="Tiến độ học tập"><div>${icon('file')}<span><strong>${s.count}</strong><small>Bài đã hoàn thành</small></span></div><div>${icon('bolt')}<span><strong>${s.best}<em> / 10</em></strong><small>Điểm cao nhất</small></span></div><div>${icon('check')}<span><strong>${s.average}<em> / 10</em></strong><small>Điểm trung bình</small></span></div><div>${icon('book')}<span><strong>${bank.length}</strong><small>Câu hỏi trong ngân hàng</small></span></div></section>
      <section><div class="section-heading"><div><h2>Ôn chắc từng bài</h2><p>5 bài học · 6 câu mỗi bài trong đề thi thử</p></div><a href="#chapters" class="text-link">Luyện theo bài ${icon('arrow')}</a></div>${chapterList()}</section>
      <section class="bottom-strip"><div class="strip-icon">${icon('file')}</div><div><h2>Mỗi lần luyện, một đề khác</h2><p>6 đề đầu phủ đủ 168 câu; thêm 6 đề trộn lại và đề ngẫu nhiên để ôn tiếp.</p></div><a href="#exams" class="btn secondary">Khám phá kho đề ${icon('arrow')}</a></section>`, 'home');
  }
  function chapterList() { return `<div class="chapter-list">${E.CHAPTERS.map(c => { const s = chapterStats(c.id); return `<div class="chapter-row"><span class="chapter-number ${c.color}">0${c.id}</span><div class="chapter-info"><h3>${c.title}</h3><p>${c.detail}</p></div><span class="question-count">${bank.filter(q => q.chapter === c.id).length} câu hỏi</span><div class="chapter-progress"><span>${s.count ? s.percent+'% trả lời đúng' : 'Chưa luyện tập'}</span><div class="track"><i style="width:${s.percent}%"></i></div></div><button class="round-button" data-action="practice" data-chapter="${c.id}" aria-label="Luyện Bài ${c.id}: ${c.title}">${icon('arrow')}</button></div>`; }).join('')}</div>`; }
  function exams() { shell(`${heading('THI THỬ NHƯ THI THẬT', 'Kho đề thi thử', 'Mỗi đề 30 câu · 45 phút · mỗi bài đúng 6 câu. Làm 6 đề đầu để gặp đủ 168 câu.')}
    <div class="random-strip"><span class="strip-icon">${icon('bolt')}</span><div><h2>Bất ngờ một chút, nhớ lâu một chút.</h2><p>Đề ngẫu nhiên đổi câu hỏi và đảo vị trí đáp án mỗi lần luyện.</p></div>${btn('random', 'Tạo đề ngẫu nhiên '+icon('arrow'))}</div><div class="section-heading"><h2>12 đề để bạn luyện dần</h2><span class="muted">Câu hỏi & đáp án của mỗi mã đề được giữ cố định</span></div><div class="exam-grid">${Array.from({ length: 12 }, (_, i) => { const seed = 20261100+i+1; const done = state.history.filter(a => a.seed === seed && a.mode === 'exam'); const best = done.length ? Math.max(...done.map(a => E.grade(a, bank).score)).toFixed(1) : null; return `<article class="exam-card"><div class="card-top"><span class="exam-symbol">${icon('file')}</span><span class="pill">${best === null ? 'Chưa làm' : 'Cao nhất '+best+'/10'}</span></div><span class="eyebrow">ĐỀ TỔNG HỢP</span><h2>Đề luyện ${String(i+1).padStart(2,'0')}</h2><p>Tổng quan đến kỹ thuật hộp đen.<br>Đủ 5 bài, cân bằng số câu.</p><div class="card-facts"><span>${icon('book')}30 câu</span><span>${icon('clock')}45 phút</span></div>${btn('preset', 'Làm đề này '+icon('arrow'), 'secondary', `data-number="${i+1}"`)}</article>`; }).join('')}</div>`, 'exams'); }
  function chapters() { shell(`${heading('LẤP ĐẦY TỪNG KHOẢNG TRỐNG', 'Luyện theo bài', 'Mỗi lượt 12 câu, không giới hạn thời gian. Xem giải thích ngay sau khi chọn đáp án.')}<div class="info-banner">${icon('book')}<span>Chế độ luyện tập giúp bạn hiểu bài. Khi đã sẵn sàng, hãy thử đề 30 câu trong 45 phút.</span></div>${chapterList()}`, 'chapters'); }
  function history() { shell(`${heading('NHÌN LẠI ĐỂ TIẾN BỘ', 'Lịch sử làm bài', 'Lưu 30 lượt gần nhất trên trình duyệt này. Chọn một lượt để xem lại đáp án.')} ${state.history.length ? `<div class="history-table"><div class="history-head"><span>BÀI LÀM</span><span>THỜI ĐIỂM</span><span>KẾT QUẢ</span><span></span></div>${state.history.map(a => { const g = E.grade(a, bank); return `<div class="history-row"><div class="history-name">${icon(a.mode === 'exam' ? 'file' : 'book')}<div><strong>${esc(a.label)}</strong><small>${a.mode === 'exam' ? 'Thi thử · 30 câu' : 'Luyện tập · 12 câu'}</small></div></div><span class="history-date">${new Date(a.finishedAt || a.startedAt).toLocaleString('vi-VN')}</span><div><strong class="history-score">${g.score.toFixed(1)}<small>/10</small></strong><span class="history-correct">${g.correct}/${g.rows.length} câu đúng</span></div>${btn('review', 'Xem lại '+icon('arrow'), 'text', `data-id="${esc(a.id)}"`)}</div>`; }).join('')}</div>` : `<div class="empty-state"><div class="empty-icon">${icon('history')}</div><h2>Hành trình bắt đầu từ đề đầu tiên.</h2><p>Kết quả và các câu cần ôn lại sẽ xuất hiện ở đây.</p>${btn('random', 'Làm một đề thử '+icon('arrow'))}</div>`}`, 'history'); }
  function sources() {
    const names = ['PDF SOTE_W01b_Overview_of_Software_Testing.pdf', 'SOTE_W02_Testing_in_the_Software_Lifecycle.pdf', 'SOTE_W03_Requirements_and_Static_Testing.pdf', 'SOTE_W04_Test_Cases_and_Test_Plans.pdf', 'SOTE_W05_Black_Box_Techniques_1.pdf'];
    shell(`${heading('BIẾT MÌNH ĐANG ÔN GÌ', 'Tài liệu & phạm vi', 'Nội dung theo Bài 1–5 trong thư mục môn học bạn cung cấp.')}<div class="source-intro"><h2>${bank.length} câu hỏi bằng tiếng Việt</h2><p>Câu hỏi được tự biên soạn từ slide và bài thực hành, gồm lý thuyết và tình huống vận dụng. Mỗi câu có giải thích và ghi tài liệu tham chiếu để bạn kiểm tra lại.</p><p>6 đề cố định đầu tiên bao phủ toàn bộ 168 câu trong ngân hàng; 6 đề tiếp theo tổ hợp lại để củng cố. Bộ câu hỏi phủ các chủ đề chính, không bảo đảm mọi chi tiết trong tài liệu hoặc mọi câu có thể ra thi. Đây là bộ đề ôn tập, không phải đề thi chính thức. Thuật ngữ tiếng Anh được giữ khi cần để đối chiếu với slide.</p></div><div class="sources-list">${E.CHAPTERS.map((c,i) => `<article><span class="chapter-number ${c.color}">0${c.id}</span><div><h2>${c.title}</h2><p class="filename">${names[i]}</p><p>${c.detail} · ${bank.filter(q => q.chapter === c.id).length} câu</p></div></article>`).join('')}</div><div class="source-intro"><h2>Cách sử dụng</h2><p><b>Thi thử:</b> 30 câu, mỗi bài 6 câu, 45 phút. Đồng hồ tiếp tục chạy khi rời trang. Hết giờ sẽ tự nộp bài; không trừ điểm câu sai.</p><p><b>Luyện theo bài:</b> 12 câu, không giới hạn thời gian, có giải thích sau mỗi câu. Đáp án đã chọn sẽ được khóa để kết quả phản ánh lần trả lời đầu tiên.</p><p><b>Tiến độ:</b> lưu trong trình duyệt hiện tại, không đồng bộ giữa các máy. Xóa dữ liệu trình duyệt sẽ xóa lịch sử. Cần một số câu lặp lại giữa các đề để ôn kiến thức cốt lõi.</p></div>`, 'sources');
  }
  function start(options) {
    const go = () => {
      const previousIds = options.previousIds || [];
      state.active = E.makeAttempt(bank, { ...options, previousIds }); save(); route = 'exam'; if (location.hash !== '#exam') location.hash = 'exam'; else render();
    };
    if (state.active?.status === 'active') confirm('Bắt đầu bài mới?', 'Bài đang làm chưa được nộp. Bắt đầu bài mới sẽ thay thế phần làm dở hiện tại.', go, 'Bắt đầu bài mới'); else go();
  }
  function finish(reason = 'manual') {
    const a = state.active; if (!a || a.status !== 'active') return;
    if (dialog.open) { confirmAction = null; dialog.close('cancel'); }
    a.status = 'done'; a.finishedAt = reason === 'timeout' ? a.deadline : Date.now(); a.reason = reason;
    state.history = [a, ...state.history.filter(x => x.id !== a.id)].slice(0,30); state.reviewId = a.id; review = a; reviewFilter = 'all'; save(); route = 'result';
    if (location.hash !== '#result') location.hash = 'result'; else render();
  }
  function timeText(seconds) { return `${String(Math.floor(seconds / 60)).padStart(2,'0')}:${String(seconds % 60).padStart(2,'0')}`; }
  function tick() {
    const a = state.active; if (!a || a.status !== 'active' || a.mode !== 'exam') return;
    const left = E.remaining(a); const el = document.getElementById('timer');
    if (el) { el.textContent = timeText(left); el.parentElement.classList.toggle('urgent', left <= 300); }
    if (left === 300 && !a.warned) { a.warned = true; save(); toast('Còn 5 phút. Bạn hãy kiểm tra các câu chưa trả lời.'); }
    if (left === 0) { finish('timeout'); toast('Đã hết 45 phút. Bài làm đã được tự động nộp.'); }
  }
  function exam() {
    const a = state.active; if (!a || a.status !== 'active') { route = 'exams'; exams(); return; }
    if (a.mode === 'exam' && E.remaining(a) === 0) { finish('timeout'); return; }
    const item = a.questions[a.current], q = lookup.get(item.id), answered = Object.keys(a.answers).length;
    const selected = a.answers[q.id], revealed = a.mode === 'practice' && selected !== undefined;
    shell(`<div class="exam-heading"><div><a href="#home" class="back-link">← Góc học tập</a><h1 tabindex="-1">${esc(a.label)}</h1><p>${a.mode === 'exam' ? '30 câu · 5 bài · Mỗi câu chỉ có một đáp án đúng' : 'Luyện 12 câu · Không giới hạn thời gian · Giải thích ngay'}</p></div><div class="timer-box ${a.mode === 'practice' ? 'practice-timer' : ''}">${icon(a.mode === 'exam' ? 'clock' : 'book')}<div><small>${a.mode === 'exam' ? 'THỜI GIAN CÒN LẠI' : 'CHẾ ĐỘ LUYỆN TẬP'}</small><strong id="timer" ${a.mode === 'exam' ? 'role="timer" aria-label="Thời gian còn lại"' : ''}>${a.mode === 'exam' ? timeText(E.remaining(a)) : 'Cứ bình tĩnh'}</strong></div></div></div><div class="exam-layout"><section class="question-card"><div class="question-top"><span class="pill">Bài ${q.chapter} · ${esc(E.CHAPTERS[q.chapter-1].short)}</span><button class="flag-button ${a.flags.includes(q.id) ? 'flagged' : ''}" data-action="flag" aria-pressed="${a.flags.includes(q.id)}">${icon('flag')} ${a.flags.includes(q.id) ? 'Đã đánh dấu' : 'Đánh dấu xem lại'}</button></div><p class="question-counter">CÂU ${String(a.current+1).padStart(2,'0')} <span>/ ${a.questions.length}</span></p><fieldset class="answers" ${revealed ? 'disabled' : ''}><legend><h2 id="question-title" tabindex="-1">${esc(q.question)}</h2></legend>${item.order.map((original,i) => `<label class="answer ${selected === original ? 'selected' : ''} ${revealed && original === q.answer ? 'correct' : ''} ${revealed && selected === original && original !== q.answer ? 'incorrect' : ''}"><input type="radio" name="answer" value="${original}" ${selected === original ? 'checked' : ''}><span class="answer-letter">${'ABCD'[i]}</span><span class="answer-text">${esc(q.options[original])}</span>${revealed && original === q.answer ? '<span class="answer-status">✓ Đúng</span>' : revealed && original === selected ? '<span class="answer-status">✕ Sai</span>' : '<span class="radio-mark"></span>'}</label>`).join('')}</fieldset>${revealed ? `<div class="explanation"><strong>${selected === q.answer ? '✓ Chính xác!' : 'Cùng xem lại nhé.'}</strong><p>${esc(q.explanation)}</p><small>${esc(q.source)}</small></div>` : ''}<div class="question-controls">${btn('prev', '← Câu trước', 'secondary', a.current === 0 ? 'disabled' : '')}<span>${a.current+1} / ${a.questions.length}</span>${a.current === a.questions.length-1 ? btn('submit', 'Nộp bài '+icon('check')) : btn('next', 'Câu tiếp '+icon('arrow'))}</div></section><aside class="question-sidebar"><div class="navigator"><h2>Phiếu trả lời</h2><div class="answer-progress"><strong>${answered}<span>/${a.questions.length} câu đã làm</span></strong><span>${Math.round(answered/a.questions.length*100)}%</span></div><div class="track"><i style="width:${answered/a.questions.length*100}%"></i></div><div class="question-grid">${a.questions.map((item,i) => `<button class="q-dot ${a.answers[item.id] !== undefined ? 'answered' : ''} ${i === a.current ? 'current' : ''} ${a.flags.includes(item.id) ? 'has-flag' : ''}" data-action="jump" data-index="${i}" aria-label="Câu ${i+1}${a.answers[item.id] !== undefined ? ', đã trả lời' : ', chưa trả lời'}${a.flags.includes(item.id) ? ', đã đánh dấu' : ''}" ${i === a.current ? 'aria-current="step"' : ''}>${i+1}</button>`).join('')}</div><div class="nav-legend"><span><i class="legend-dot done"></i>Đã trả lời</span><span><i class="legend-dot"></i>Chưa trả lời</span><span><i class="legend-dot marked"></i>Đánh dấu</span></div>${btn('submit', 'Nộp bài & xem kết quả', 'primary wide')}</div><p class="save-hint">${icon('check')} ${storageWarning ? 'Chưa lưu được tiến độ. Hãy giữ trang mở.' : 'Tự động lưu sau mỗi câu trả lời.'}${a.mode === 'exam' ? '<br>Đồng hồ vẫn chạy khi bạn rời trang.' : ''}</p></aside></div>`, a.mode === 'exam' ? 'exams' : 'chapters');
  }
  function results() {
    const a = review || state.history.find(x => x.id === state.reviewId) || (state.active?.status === 'done' ? state.active : state.history[0]); if (!a) { history(); return; } review = a;
    const g = E.grade(a, bank); const filtered = g.rows.filter(q => reviewFilter === 'all' || reviewFilter === 'wrong' && !q.correct || reviewFilter === 'flags' && a.flags.includes(q.id));
    const elapsed = Math.max(0, Math.floor(((a.finishedAt || Date.now())-a.startedAt)/1000));
    shell(`${heading('MỖI LẦN LÀM LÀ MỘT LẦN HỌC', 'Bạn đã hoàn thành bài làm.', esc(a.label)+(a.reason === 'timeout' ? ' · Tự động nộp khi hết giờ' : ' · Cảm ơn bạn đã dành thời gian luyện tập.'))}<section class="result-overview"><div class="score-circle"><strong>${g.score.toFixed(1)}</strong><span>ĐIỂM / 10</span></div><div class="result-message"><span class="eyebrow">${g.score >= 8 ? 'GIỮ VỮNG PHONG ĐỘ' : g.score >= 5 ? 'BẠN ĐANG TIẾN BỘ' : 'CỨ TỪNG BƯỚC MỘT'}</span><h2>${g.score >= 8 ? 'Một lượt luyện rất chắc tay.' : g.score >= 5 ? 'Thêm một chút ôn, thêm nhiều tự tin.' : 'Đã biết chỗ cần ôn. Mình tiếp tục nhé.'}</h2><p><b>${g.correct}</b> câu đúng <span>·</span> <b>${g.rows.length-g.correct-g.unanswered}</b> câu sai <span>·</span> <b>${g.unanswered}</b> chưa trả lời <span>·</span> ${Math.floor(elapsed/60)} phút ${elapsed%60} giây</p><div class="result-actions">${btn('retry', 'Luyện một lượt khác '+icon('arrow'))}<a href="#history" class="btn secondary">Xem lịch sử</a></div></div></section><section class="chapter-results">${g.chapters.map(c => `<div><span>Bài ${c.id} · ${c.short}</span><strong>${c.correct}<small>/${c.total} đúng</small></strong><div class="track"><i style="width:${c.correct/c.total*100}%"></i></div></div>`).join('')}</section><div class="section-heading review-heading"><div><h2>Xem lại để nhớ lâu hơn</h2><p>Mỗi câu đúng tính ${a.mode === 'exam' ? '1/3' : '10/12'} điểm; câu sai hoặc bỏ trống không có điểm.</p></div><div class="filter-group" aria-label="Lọc câu xem lại">${[['all','Tất cả ('+g.rows.length+')'],['wrong','Sai & bỏ trống ('+(g.rows.length-g.correct)+')'],['flags','Đánh dấu ('+a.flags.length+')']].map(([value,label]) => `<button data-action="filter" data-filter="${value}" class="${reviewFilter===value ? 'active' : ''}" aria-pressed="${reviewFilter===value}">${label}</button>`).join('')}</div></div><div class="review-list">${filtered.length ? filtered.map(q => `<article class="review-card"><div class="review-meta"><span>BÀI ${q.chapter} <span>·</span> CÂU ${g.rows.findIndex(x => x.id === q.id)+1}</span><span class="result-badge ${q.correct ? 'right' : 'wrong'}">${q.correct ? '✓ Đúng' : q.selected === undefined ? '— Chưa trả lời' : '✕ Sai'}</span></div><h3>${esc(q.question)}</h3><div class="review-options">${q.order.map((original,i) => `<div class="review-option ${original === q.answer ? 'right' : q.selected === original ? 'wrong' : ''}"><b>${'ABCD'[i]}.</b><span>${esc(q.options[original])}</span><small>${original === q.answer ? '✓ Đáp án đúng' : original === q.selected ? '✕ Bạn đã chọn' : ''}</small></div>`).join('')}</div><div class="review-explanation"><strong>Vì sao?</strong><p>${esc(q.explanation)}</p><small>${esc(q.source)}</small></div></article>`).join('') : '<div class="empty-state compact"><h3>Không có câu nào trong nhóm này.</h3><p>Bạn có thể chuyển sang Tất cả để xem lại bài làm.</p></div>'}</div>`, 'history');
  }
  function render() {
    if (route === 'exam') exam(); else if (route === 'exams') exams(); else if (route === 'chapters') chapters(); else if (route === 'history') history(); else if (route === 'sources') sources(); else if (route === 'result') results(); else home();
    tick();
  }
  function goQuestion(index) { const a = state.active; a.current = Math.max(0, Math.min(a.questions.length-1,index)); save(); exam(); document.getElementById('question-title')?.focus({ preventScroll: true }); if (innerWidth < 850) window.scrollTo({ top: 0, behavior: 'smooth' }); }
  app.addEventListener('click', event => {
    const target = event.target.closest('[data-action]'); if (!target) return;
    const action = target.dataset.action, a = state.active;
    if (action === 'random') start({ seed: crypto.getRandomValues(new Uint32Array(1))[0], label: 'Đề ngẫu nhiên', previousIds: state.history.find(x => x.mode === 'exam')?.questions.map(q => q.id) || [] });
    else if (action === 'preset') start({ seed: 20261100+Number(target.dataset.number), setNumber: Number(target.dataset.number), label: 'Đề luyện '+target.dataset.number.padStart(2,'0') });
    else if (action === 'practice') start({ seed: crypto.getRandomValues(new Uint32Array(1))[0], mode: 'practice', chapter: Number(target.dataset.chapter), label: 'Luyện Bài '+target.dataset.chapter+' · '+E.CHAPTERS[Number(target.dataset.chapter)-1].short });
    else if (action === 'resume') { location.hash = 'exam'; }
    else if (action === 'review') { review = state.history.find(x => x.id === target.dataset.id); state.reviewId = review?.id || null; save(); reviewFilter = 'all'; location.hash = 'result'; if (route === 'result') results(); }
    else if (action === 'filter') { reviewFilter = target.dataset.filter; results(); }
    else if (action === 'retry' && review) { start({ seed: crypto.getRandomValues(new Uint32Array(1))[0], mode: review.mode, chapter: review.chapter, label: review.mode === 'exam' ? 'Đề ngẫu nhiên' : review.label, previousIds: review.questions.map(q => q.id) }); }
    else if (a?.status === 'active') {
      if (a.mode === 'exam' && E.remaining(a) === 0) { tick(); return; }
      if (action === 'next') goQuestion(a.current+1);
      if (action === 'prev') goQuestion(a.current-1);
      if (action === 'jump') goQuestion(Number(target.dataset.index));
      if (action === 'flag') { const id = a.questions[a.current].id; a.flags = a.flags.includes(id) ? a.flags.filter(x => x !== id) : [...a.flags,id]; save(); exam(); app.querySelector('[data-action="flag"]')?.focus(); }
      if (action === 'submit') { const left = a.questions.length-Object.keys(a.answers).length; confirm('Nộp bài làm?', left ? `Bạn còn ${left} câu chưa trả lời. Câu bỏ trống không được tính điểm. Bạn vẫn có thể quay lại làm tiếp.` : 'Bạn đã trả lời tất cả câu hỏi. Nộp bài để xem điểm, đáp án và giải thích.', () => finish(), 'Nộp bài & xem kết quả'); }
    }
  });
  app.addEventListener('change', event => {
    if (!event.target.matches('input[name="answer"]')) return;
    const a = state.active; if (!a || a.status !== 'active') return;
    if (a.mode === 'exam' && E.remaining(a) === 0) { tick(); return; }
    const id = a.questions[a.current].id;
    if (a.mode === 'practice' && a.answers[id] !== undefined) return;
    const value = Number(event.target.value); if (!Number.isInteger(value) || value < 0 || value > 3) return;
    a.answers[id] = value; save(); exam();
    if (a.mode === 'exam') app.querySelector(`input[value="${value}"]`)?.focus(); else app.querySelector('[data-action="next"], [data-action="submit"]')?.focus({ preventScroll: true });
  });
  window.addEventListener('hashchange', () => { route = location.hash.slice(1) || 'home'; render(); document.querySelector('h1')?.focus({ preventScroll: true }); window.scrollTo(0,0); });
  document.querySelector('.skip').addEventListener('click', event => { event.preventDefault(); document.getElementById('main')?.focus(); document.getElementById('main')?.scrollIntoView(); });
  document.addEventListener('visibilitychange', tick);
  window.addEventListener('pageshow', tick);
  route = location.hash.slice(1) || 'home'; render(); setInterval(tick, 1000);
  if (storageWarning) toast('Trình duyệt không đọc được tiến độ đã lưu. Bài mới vẫn có thể làm bình thường.');
})();
